patch:
diff --git a/repro/no-var-20209.js b/repro/no-var-20209.js
new file mode 100644
index 0000000..98b661f
--- /dev/null
+++ b/repro/no-var-20209.js
@@ -0,0 +1,39 @@
+"use strict";
+// Repro for eslint#20209: no-var autofix turns `var` into `let` when used before declaration.
+// Usage: node repro/no-var-20209.js [path-to-eslint-package-root]   (default: this checkout)
+const path = require("node:path");
+const vm = require("node:vm");
+const root = path.resolve(process.argv[2] || path.join(__dirname, ".."));
+const { Linter } = require(path.join(root, "lib/api"));
+const version = require(path.join(root, "package.json")).version;
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+
+const linter = new Linter({ configType: "flat" });
+const config = [{ rules: { "no-var": "error" } }];
+const messages = linter.verify(code, config, "x.js");
+const { output, fixed } = linter.verifyAndFix(code, config, "x.js");
+
+function run(src) {
+    const body = src.replace(/^export /u, "") + "\na();";
+    try {
+        vm.runInNewContext(body, { console: { log() {} } });
+        return "ok";
+    } catch (e) {
+        return `${e.name}: ${e.message}`;
+    }
+}
+
+console.log(`eslint ${version} (${root})`);
+console.log("messages:", messages.map(m => `${m.line}:${m.column} ${m.message} fix=${Boolean(m.fix)}`));
+console.log("fixed:", fixed);
+console.log("--- output ---\n" + output + "\n--------------");
+console.log("run original:", run(code));
+console.log("run output:  ", run(output));
+const bug = fixed && run(output) !== "ok";
+console.log(bug ? "BUG REPRODUCED: autofix output throws" : "no bug: autofix does not produce failing code");
+process.exitCode = bug ? 1 : 0;
